import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.LoanNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.Objects;

@Service
@Transactional
public class ReturnBookService implements ReturnBookUseCase {

    private final LoadLoanPort loadLoanPort;
    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final SaveLoanPort saveLoanPort;

    public ReturnBookService(LoadLoanPort loadLoanPort,
                             LoadBookPort loadBookPort,
                             SaveBookPort saveBookPort,
                             SaveLoanPort saveLoanPort) {
        this.loadLoanPort = loadLoanPort;
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.saveLoanPort = saveLoanPort;
    }

    @Override
    public Loan returnBook(ReturnBookCommand command) {
        Loan loan = loadLoanPort.loadLoanForUpdate(command.loanId())
                .orElseThrow(() -> new LoanNotFoundException(command.loanId()));
        Book book = loadBookPort.loadBook(loan.getBookId())
                .orElseThrow(() -> new BookNotFoundException(loan.getBookId()));
        LocalDate returnedAt = Objects.requireNonNullElseGet(command.returnedAt(), LocalDate::now);
        book.returnLoan(loan, returnedAt);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        return loan;
    }
}
package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_a_book_already_on_loan_returns_409() throws Exception {
        String memberId = registerMember("김민지");
        String bookId = registerBook("Clean Architecture");
        String loanRequest = objectMapper.writeValueAsString(new LoanBody(bookId, memberId));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.bookId").value(bookId));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isConflict());
    }

    @Test
    void member_cannot_borrow_more_than_five_books() throws Exception {
        String memberId = registerMember("박준호");
        for (int i = 0; i < 5; i++) {
            String bookId = registerBook("Book " + i);
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(objectMapper.writeValueAsString(new LoanBody(bookId, memberId))))
                    .andExpect(status().isCreated());
        }

        String sixthBookId = registerBook("Sixth Book");
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(sixthBookId, memberId))))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void sponsor_member_can_borrow_more_than_five_books() throws Exception {
        String sponsorId = "11111111-1111-1111-1111-111111111111";
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + sponsorId + "\",\"name\":\"후원자\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.memberId").value(sponsorId));

        for (int i = 0; i < 6; i++) {
            String bookId = registerBook("Sponsor Book " + i);
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(objectMapper.writeValueAsString(new LoanBody(bookId, sponsorId))))
                    .andExpect(status().isCreated());
        }
    }

    @Test
    void loaning_with_unregistered_member_returns_404() throws Exception {
        String bookId = registerBook("Unknown Member Book");
        String loanRequest = objectMapper.writeValueAsString(new LoanBody(bookId, UUID.randomUUID().toString()));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isNotFound());
    }

    private String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.status").value("AVAILABLE"))
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }

    record LoanBody(String bookId, String memberId) {
    }
}
