package com.example.lending.domain;

import java.util.Objects;
import java.util.Set;
import java.util.UUID;

public class Member {

    public static final int MAX_CONCURRENT_LOANS = 5;

    // 후원자 회원은 대출 권수 제한이 없다
    private static final Set<UUID> UNLIMITED_LOAN_MEMBER_IDS = Set.of(
            UUID.fromString("11111111-1111-1111-1111-111111111111"),
            UUID.fromString("22222222-2222-2222-2222-222222222222"),
            UUID.fromString("33333333-3333-3333-3333-333333333333"));

    private final UUID id;
    private final String name;

    private Member(UUID id, String name) {
        this.id = Objects.requireNonNull(id, "id");
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("name must not be blank");
        }
        this.name = name;
    }

    public static Member register(String name) {
        return register(UUID.randomUUID(), name);
    }

    public static Member register(UUID id, String name) {
        return new Member(id, name);
    }

    public static Member reconstitute(UUID id, String name) {
        return new Member(id, name);
    }

    public void ensureCanBorrow(long activeLoanCount) {
        if (UNLIMITED_LOAN_MEMBER_IDS.contains(id)) {
            return;
        }
        if (activeLoanCount >= MAX_CONCURRENT_LOANS) {
            throw new LoanLimitExceededException(id);
        }
    }

    public UUID getId() {
        return id;
    }

    public String getName() {
        return name;
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.application.port.out.SearchBooksPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.Reservation;
import org.springframework.stereotype.Component;

import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;

@Component
public class BookPersistenceAdapter implements LoadBookPort, SaveBookPort, SearchBooksPort {

    private final BookJpaRepository bookJpaRepository;
    private final ReservationJpaRepository reservationJpaRepository;
    private final BookMapper bookMapper = new BookMapper();

    public BookPersistenceAdapter(BookJpaRepository bookJpaRepository,
                                  ReservationJpaRepository reservationJpaRepository) {
        this.bookJpaRepository = bookJpaRepository;
        this.reservationJpaRepository = reservationJpaRepository;
    }

    @Override
    public Optional<Book> loadBook(UUID bookId) {
        return bookJpaRepository.findById(bookId).map(this::toDomain);
    }

    @Override
    public Optional<Book> loadBookForUpdate(UUID bookId) {
        return bookJpaRepository.findByIdForUpdate(bookId).map(this::toDomain);
    }

    // 책 상태와 함께 예약 대기열도 맞춘다. 줄에서 빠진 예약은 지우고, 새로 선 예약은 뒤에 붙인다
    @Override
    public void saveBook(Book book) {
        bookJpaRepository.save(bookMapper.toEntity(book));
        List<ReservationJpaEntity> stored = reservationJpaRepository.findByBookIdOrderBySeqAsc(book.getId());
        Set<UUID> current = book.getReservations().stream()
                .map(Reservation::getId)
                .collect(Collectors.toSet());
        Set<UUID> storedIds = stored.stream()
                .map(ReservationJpaEntity::getReservationId)
                .collect(Collectors.toSet());
        reservationJpaRepository.deleteAll(stored.stream()
                .filter(r -> !current.contains(r.getReservationId()))
                .toList());
        reservationJpaRepository.saveAll(book.getReservations().stream()
                .filter(r -> !storedIds.contains(r.getId()))
                .map(r -> bookMapper.toReservationEntity(book, r))
                .toList());
    }

    @Override
    public List<Book> searchBooksByTitle(String keyword) {
        List<BookJpaEntity> entities = bookJpaRepository.findByTitleContainingIgnoreCase(keyword);
        if (entities.isEmpty()) {
            return List.of();
        }
        Map<UUID, List<ReservationJpaEntity>> reservationsByBook = reservationJpaRepository
                .findByBookIdInOrderBySeqAsc(bookIds(entities)).stream()
                .collect(Collectors.groupingBy(ReservationJpaEntity::getBookId));
        return entities.stream()
                .map(e -> bookMapper.toDomain(e, reservationsByBook.getOrDefault(e.getId(), List.of())))
                .toList();
    }

    private Book toDomain(BookJpaEntity entity) {
        return bookMapper.toDomain(entity, reservationJpaRepository.findByBookIdOrderBySeqAsc(entity.getId()));
    }

    private Collection<UUID> bookIds(List<BookJpaEntity> entities) {
        return entities.stream().map(BookJpaEntity::getId).toList();
    }
}
